// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Bounded deterministic-task experiment, not a general VM or AI fault proof.
contract BoundedTaskRollup {
    enum Phase { NONE, SUBMITTED, OPEN, RESPONDED, LOCATING, READY, VERIFIED, SETTLED }
    struct TaskInput {
        bytes32 taskId;
        bytes32 initial;
        uint16 steps;
        uint32 version;
        bytes32 output;
        bytes32 traceRoot;
        bytes32 dataHash;
    }
    struct Task {
        TaskInput input;
        address submitter;
        address challenger;
        Phase phase;
        uint64 challengeDeadline;
        uint64 absoluteDeadline;
        uint64 timeoutAt;
        uint8 recoveries;
        uint16 left;
        uint16 right;
        uint16 round;
        uint16 firstMismatch;
        bytes32 evidenceRoot;
        uint8 verdict;
    }
    uint32 public constant TASK_VERSION = 1;
    uint16 public constant MAX_STEPS = 128;
    bytes32 public constant DOMAIN = keccak256("HYBRID_BOUNDED_TASK_V1");
    uint256 public immutable bond;
    uint64 public immutable challengeWindow;
    uint64 public immutable stepTimeout;
    uint8 public immutable maxRecoveries;
    mapping(bytes32 => Task) private tasks;
    mapping(address => uint256) public claimable;
    uint256 public locked;
    uint256 public totalClaimable;
    uint256 public totalDeposited;
    uint256 public totalWithdrawn;
    bool private withdrawing;
    event Submitted(bytes32 indexed taskId, address indexed submitter, bytes32 digest, uint64 challengeDeadline);
    event Challenged(bytes32 indexed taskId, address indexed challenger, uint64 absoluteDeadline);
    event Responded(bytes32 indexed taskId, bytes32 evidenceRoot, uint16 firstMismatch);
    event Advanced(bytes32 indexed taskId, uint16 left, uint16 right, uint16 round);
    event Recovered(bytes32 indexed taskId, address indexed observer, uint8 count, uint64 timeoutAt);
    event Verified(bytes32 indexed taskId, uint8 verdict);
    event Settled(bytes32 indexed taskId, uint8 verdict, address indexed winner, uint256 amount);
    event Withdrawn(address indexed owner, address indexed recipient, uint256 amount);

    constructor(uint256 bond_, uint64 challengeWindow_, uint64 stepTimeout_, uint8 maxRecoveries_) {
        require(bond_ > 0 && stepTimeout_ >= 2 && challengeWindow_ > 0, "config");
        require(maxRecoveries_ <= 2, "recovery config");
        bond = bond_; challengeWindow = challengeWindow_; stepTimeout = stepTimeout_; maxRecoveries = maxRecoveries_;
    }
    function getTask(bytes32 id) external view returns (Task memory) { return tasks[id]; }
    function taskDigest(TaskInput memory t) public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN, block.chainid, address(this), t));
    }
    // x_0 is included; root = keccak256(abi.encode(bytes32[n+1])). This is an ordered
    // vector commitment, deliberately NOT a Merkle root or a single-step proof.
    function compute(bytes32 initial, uint16 steps) public pure returns (bytes32 output, bytes32 root) {
        require(steps >= 1 && steps <= MAX_STEPS, "steps");
        bytes32[] memory trace = new bytes32[](uint256(steps) + 1);
        trace[0] = initial;
        for (uint256 i = 0; i < steps; ++i) trace[i + 1] = keccak256(abi.encode(i, trace[i]));
        return (trace[steps], keccak256(abi.encode(trace)));
    }
    function submit(TaskInput calldata input, bytes calldata signature) external payable {
        require(msg.value == bond, "bond");
        require(input.taskId != bytes32(0) && tasks[input.taskId].phase == Phase.NONE, "task id");
        require(input.steps >= 1 && input.steps <= MAX_STEPS && input.version == TASK_VERSION, "task bounds");
        require(_signer(taskDigest(input), signature) == msg.sender, "signature");
        Task storage t = tasks[input.taskId];
        t.input = input; t.submitter = msg.sender; t.phase = Phase.SUBMITTED;
        t.challengeDeadline = uint64(block.timestamp + challengeWindow);
        locked += msg.value; totalDeposited += msg.value;
        emit Submitted(input.taskId, msg.sender, taskDigest(input), t.challengeDeadline);
    }
    function normalTransitions(uint16 steps) public pure returns (uint16) {
        require(steps >= 1 && steps <= MAX_STEPS, "steps");
        uint16 rounds; uint16 width = steps + 1;
        while (width > 1) { width = (width + 1) / 2; ++rounds; }
        return rounds + 3; // response + bisection rounds + verification + settlement
    }
    function openChallenge(bytes32 id) external payable {
        Task storage t = tasks[id];
        require(t.phase == Phase.SUBMITTED, "phase");
        require(block.timestamp <= t.challengeDeadline, "window");
        require(msg.sender != t.submitter && msg.value == bond, "challenger bond");
        t.challenger = msg.sender; t.phase = Phase.OPEN; t.right = t.input.steps;
        t.absoluteDeadline = uint64(block.timestamp + uint256(normalTransitions(t.input.steps) + maxRecoveries) * stepTimeout);
        _touch(t); locked += msg.value; totalDeposited += msg.value;
        emit Challenged(id, msg.sender, t.absoluteDeadline);
    }
    // Optional diagnostic response, not an obligation punishable by an offline timeout.
    // A third party cannot replace the committed trace. Correctness is checked separately.
    function respond(bytes32 id, bytes32[] calldata trace) external {
        Task storage t = tasks[id];
        require(t.phase == Phase.OPEN, "phase");
        require(msg.sender == t.submitter, "submitter only"); _live(t);
        require(trace.length == uint256(t.input.steps) + 1, "trace length");
        require(keccak256(abi.encode(trace)) == t.input.traceRoot, "trace binding");
        bytes32 expected = t.input.initial;
        uint16 first = t.input.steps; bool found;
        for (uint16 i = 0; i <= t.input.steps; ++i) {
            if (!found && trace[i] != expected) { first = i; found = true; }
            if (i < t.input.steps) expected = keccak256(abi.encode(uint256(i), expected));
        }
        t.firstMismatch = first;
        t.evidenceRoot = keccak256(abi.encode(taskDigest(t.input), t.input.traceRoot));
        t.phase = Phase.RESPONDED; _touch(t);
        emit Responded(id, t.evidenceRoot, first);
    }
    function advance(bytes32 id) external {
        Task storage t = tasks[id];
        require(t.phase == Phase.RESPONDED || t.phase == Phase.LOCATING, "phase"); _live(t);
        require(t.left < t.right, "already located");
        uint16 mid = (t.left + t.right) / 2;
        if (t.firstMismatch <= mid) t.right = mid; else t.left = mid + 1;
        ++t.round; t.phase = t.left == t.right ? Phase.READY : Phase.LOCATING; _touch(t);
        emit Advanced(id, t.left, t.right, t.round);
    }
    function recover(bytes32 id) external {
        Task storage t = tasks[id];
        require(t.phase >= Phase.OPEN && t.phase <= Phase.READY, "phase");
        require(block.timestamp > t.timeoutAt && block.timestamp < t.absoluteDeadline, "recovery time");
        require(t.recoveries < maxRecoveries, "recovery limit");
        ++t.recoveries; _touch(t);
        emit Recovered(id, msg.sender, t.recoveries, t.timeoutAt);
    }
    function replay(bytes32 id) external {
        Task storage t = tasks[id]; require(t.phase == Phase.READY, "phase"); _live(t);
        _verify(t, id);
    }
    // Anyone may bypass optional localization: all deterministic inputs are already public.
    // This path remains available at and after every deadline, even with both parties offline.
    function adjudicate(bytes32 id) external {
        Task storage t = tasks[id];
        require(t.phase >= Phase.OPEN && t.phase < Phase.SETTLED, "phase");
        if (t.phase != Phase.VERIFIED) _verify(t, id);
        _settle(t, id, t.challenger);
    }
    function settle(bytes32 id) external {
        Task storage t = tasks[id]; require(t.phase == Phase.VERIFIED, "phase"); _settle(t, id, t.challenger);
    }
    function terminate(bytes32 id) external {
        Task storage t = tasks[id];
        require(t.phase >= Phase.OPEN && t.phase < Phase.SETTLED, "phase");
        require(block.timestamp > t.timeoutAt || block.timestamp >= t.absoluteDeadline, "not timed out");
        if (t.phase != Phase.VERIFIED) _verify(t, id);
        _settle(t, id, t.challenger);
    }
    function finalize(bytes32 id) external {
        Task storage t = tasks[id]; require(t.phase == Phase.SUBMITTED, "phase");
        require(block.timestamp > t.challengeDeadline, "window");
        _verify(t, id); _settle(t, id, msg.sender);
    }
    function withdraw(address payable recipient) external {
        require(!withdrawing && recipient != address(0), "withdraw guard");
        uint256 amount = claimable[msg.sender]; require(amount > 0, "no balance");
        withdrawing = true; claimable[msg.sender] = 0; totalClaimable -= amount; totalWithdrawn += amount;
        (bool ok,) = recipient.call{value: amount}(""); require(ok, "transfer failed");
        withdrawing = false; emit Withdrawn(msg.sender, recipient, amount);
    }
    function _verify(Task storage t, bytes32 id) private {
        (bytes32 output, bytes32 root) = compute(t.input.initial, t.input.steps);
        // bit 0: incorrect final output; bit 1: incorrect ordered trace commitment.
        t.verdict = (output != t.input.output ? 1 : 0) | (root != t.input.traceRoot ? 2 : 0);
        t.phase = Phase.VERIFIED; emit Verified(id, t.verdict);
    }
    function _settle(Task storage t, bytes32 id, address errorRecipient) private {
        uint256 amount = t.challenger == address(0) ? bond : 2 * bond;
        address winner = t.verdict == 0 ? t.submitter : errorRecipient;
        t.phase = Phase.SETTLED; locked -= amount; claimable[winner] += amount; totalClaimable += amount;
        emit Settled(id, t.verdict, winner, amount);
    }
    function _live(Task storage t) private view {
        require(block.timestamp <= t.timeoutAt && block.timestamp < t.absoluteDeadline, "timed out");
    }
    function _touch(Task storage t) private {
        uint256 deadline = block.timestamp + stepTimeout;
        t.timeoutAt = uint64(deadline < t.absoluteDeadline ? deadline : t.absoluteDeadline);
    }
    function _signer(bytes32 digest, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r; bytes32 s; uint8 v;
        assembly { r := calldataload(sig.offset) s := calldataload(add(sig.offset, 32)) v := byte(0, calldataload(add(sig.offset, 64))) }
        if ((v != 27 && v != 28) || uint256(s) > 0x7fffffffffffffffffffffffffffffff5d576e7357a4501ddfe92f46681b20a0) return address(0);
        return ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", digest)), v, r, s);
    }
}

contracts/HybridTEERollup.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./MerkleVerifier.sol";
import "./MockDARegistry.sol";
import "./MockTEEVerifier.sol";

contract HybridTEERollup {
    using MerkleVerifier for bytes32;

    enum TxStatus {
        NONE,
        PENDING,
        FINALIZED,
        SLASHED
    }

    enum ChallengeStatus {
        NONE,
        OPEN,
        RESPONDED,
        NARROWING,
        READY_FOR_REPLAY,
        REPLAYED,
        RECOVERED,
        RESOLVED
    }

    struct Commit {
        bytes32 stateRoot;
        bytes32 outputHash;
        bytes32 proofHash;
        bytes32 daPointer;
        bytes32 daMerkleRoot;
    }

    struct RollupTransaction {
        bool exists;
        TxStatus status;
        address submitter;
        bytes32 inputHash;
        bytes32 mrenclave;
        uint256 createdAt;
        uint256 challengeDeadline;
        bytes32 attestationNonce;
        Commit commit;
    }

    struct ChallengeEvidence {
        bool daAvailable;
        bool daProofValid;
        uint256 mismatchBits;
        uint256 targetStep;
        bytes32 expectedHash;
        bytes32 claimedHash;
    }

    struct DisputeState {
        uint256 left;
        uint256 right;
        uint256 round;
        uint256 traceLength;
        bool lengthMismatch;
        bool narrowingComplete;
        uint256 targetStep;
        bool replayExecuted;
        bool replayPassed;
    }

    struct RecoveryState {
        uint256 count;
        uint256 lastRecoveredAt;
        uint256 lastPriorRound;
        ChallengeStatus lastPriorStatus;
    }

    struct ChallengeSession {
        bool exists;
        address challenger;
        address responder;
        address operator;
        address arbitrator;
        ChallengeStatus status;
        uint256 openedAt;
        uint256 lastUpdatedAt;
        uint256 timeoutAt;
        uint256 resolvedAt;
        bool challengeSuccess;
        uint256 resolutionBits;
        ChallengeEvidence evidence;
        DisputeState dispute;
        RecoveryState recovery;
    }

    MockTEEVerifier public immutable teeVerifier;
    MockDARegistry public immutable daRegistry;
    uint256 public immutable defaultDisputeWindowSeconds;
    uint256 public immutable defaultChallengeTimeoutSeconds;
    uint256 public immutable defaultMaxBisectionRounds;

    mapping(bytes32 => RollupTransaction) private transactions;
    mapping(bytes32 => ChallengeSession) private sessions;

    event TransactionSubmitted(bytes32 indexed txId, address indexed submitter, bytes32 daPointer);
    event ChallengeOpened(bytes32 indexed txId, address indexed challenger, uint256 traceLength);
    event ChallengeResponded(bytes32 indexed txId, address indexed responder, uint256 mismatchBits);
    event ChallengeStepped(bytes32 indexed txId, uint256 round, uint256 left, uint256 right, bool complete);
    event ChallengeRecovered(bytes32 indexed txId, address indexed operator, ChallengeStatus restoredStatus);
    event ChallengeReplayed(bytes32 indexed txId, uint256 targetStep, bool passed);
    event ChallengeResolved(bytes32 indexed txId, bool challengeSuccess, TxStatus txStatus);
    event TransactionFinalized(bytes32 indexed txId);

    constructor(
        address teeVerifier_,
        address daRegistry_,
        uint256 disputeWindowSeconds_,
        uint256 challengeTimeoutSeconds_,
        uint256 maxBisectionRounds_
    ) {
        require(teeVerifier_ != address(0), "invalid verifier");
        require(daRegistry_ != address(0), "invalid da registry");
        teeVerifier = MockTEEVerifier(teeVerifier_);
        daRegistry = MockDARegistry(daRegistry_);
        defaultDisputeWindowSeconds = disputeWindowSeconds_;
        defaultChallengeTimeoutSeconds = challengeTimeoutSeconds_;
        defaultMaxBisectionRounds = maxBisectionRounds_;
    }

    function submitRollup(
        bytes32 txId,
        bytes32 inputHash,
        bytes32 mrenclave,
        bytes32 attestationNonce,
        bytes calldata attestationSignature,
        Commit calldata commit
    ) external {
        require(txId != bytes32(0), "invalid tx id");
        require(!transactions[txId].exists, "tx exists");

        MockDARegistry.DARecord memory daRecord = daRegistry.getRecord(commit.daPointer);
        require(daRecord.available, "da unavailable");
        require(daRecord.merkleRoot == commit.daMerkleRoot, "da root mismatch");
        require(
            teeVerifier.verifyAttestation(
                inputHash,
                commit.outputHash,
                attestationNonce,
                mrenclave,
                attestationSignature
            ),
            "attestation invalid"
        );
        require(
            teeVerifier.computeProofHash(attestationNonce, attestationSignature) == commit.proofHash,
            "proof hash mismatch"
        );

        transactions[txId] = RollupTransaction({
            exists: true,
            status: TxStatus.PENDING,
            submitter: msg.sender,
            inputHash: inputHash,
            mrenclave: mrenclave,
            createdAt: block.timestamp,
            challengeDeadline: block.timestamp + defaultDisputeWindowSeconds,
            attestationNonce: attestationNonce,
            commit: commit
        });

        emit TransactionSubmitted(txId, msg.sender, commit.daPointer);
    }

    function openChallenge(
        bytes32 txId,
        uint256 mismatchBits,
        uint256 traceLength,
        bool lengthMismatch,
        bytes32 fieldKeyHash,
        bytes32 fieldValueHash,
        bytes32[] calldata siblingHashes,
        bool[] calldata siblingOnLeft
    ) external {
        RollupTransaction storage transaction = transactions[txId];
        require(transaction.exists, "tx missing");
        require(transaction.status == TxStatus.PENDING, "tx not pending");
        require(block.timestamp <= transaction.challengeDeadline, "challenge window closed");
        require(!_isActiveSession(txId), "challenge already active");

        bool daAvailable = daRegistry.isAvailable(transaction.commit.daPointer);
        bool daProofValid = daAvailable
            && MerkleVerifier.verify(
                transaction.commit.daMerkleRoot,
                fieldKeyHash,
                fieldValueHash,
                siblingHashes,
                siblingOnLeft
            );

        ChallengeSession storage session = sessions[txId];
        delete sessions[txId];
        session.exists = true;
        session.challenger = msg.sender;
        session.status = ChallengeStatus.OPEN;
        session.openedAt = block.timestamp;
        session.lastUpdatedAt = block.timestamp;
        session.timeoutAt = block.timestamp + defaultChallengeTimeoutSeconds;
        session.evidence.daAvailable = daAvailable;
        session.evidence.daProofValid = daProofValid;
        session.evidence.mismatchBits = mismatchBits;

        if (traceLength == 0) {
            session.dispute.left = 0;
            session.dispute.right = 0;
            session.dispute.traceLength = 0;
            session.dispute.lengthMismatch = lengthMismatch;
            session.dispute.narrowingComplete = true;
            session.dispute.targetStep = 0;
            session.status = ChallengeStatus.READY_FOR_REPLAY;
        } else {
            session.dispute.left = 0;
            session.dispute.right = lengthMismatch ? traceLength : traceLength - 1;
            session.dispute.traceLength = traceLength;
            session.dispute.lengthMismatch = lengthMismatch;
            session.dispute.narrowingComplete = traceLength <= 1;
            if (session.dispute.narrowingComplete) {
                session.dispute.targetStep = 0;
                session.status = ChallengeStatus.READY_FOR_REPLAY;
            }
        }

        emit ChallengeOpened(txId, msg.sender, traceLength);
    }

    function respondChallenge(bytes32 txId, uint256 previewMismatchBits) external {
        ChallengeSession storage session = sessions[txId];
        require(session.exists && session.status == ChallengeStatus.OPEN, "no open challenge");
        require(!_isTimedOut(session), "challenge timed out");

        session.responder = msg.sender;
        session.status = ChallengeStatus.RESPONDED;
        session.evidence.mismatchBits |= previewMismatchBits;
        _touchSession(session);

        emit ChallengeResponded(txId, msg.sender, session.evidence.mismatchBits);
    }

    function stepChallenge(bytes32 txId, uint256 observedMismatchIndex) external {
        ChallengeSession storage session = sessions[txId];
        require(session.exists && _isActiveStatus(session.status), "no active challenge");
        require(!_isTimedOut(session), "challenge timed out");

        DisputeState storage dispute = session.dispute;
        require(dispute.round < defaultMaxBisectionRounds, "max rounds reached");

        if (dispute.traceLength == 0) {
            dispute.narrowingComplete = true;
            dispute.targetStep = 0;
            session.status = ChallengeStatus.READY_FOR_REPLAY;
            _touchSession(session);
            emit ChallengeStepped(txId, dispute.round, dispute.left, dispute.right, true);
            return;
        }

        if (dispute.narrowingComplete) {
            session.status = ChallengeStatus.READY_FOR_REPLAY;
            _touchSession(session);
            emit ChallengeStepped(txId, dispute.round, dispute.left, dispute.right, true);
            return;
        }

        uint256 mid = (dispute.left + dispute.right) / 2;
        if (observedMismatchIndex <= mid) {
            dispute.right = mid;
        } else {
            dispute.left = mid + 1;
        }
        dispute.round += 1;

        if (dispute.left >= dispute.right) {
            dispute.narrowingComplete = true;
            dispute.targetStep = dispute.left;
            session.status = ChallengeStatus.READY_FOR_REPLAY;
        } else {
            session.status = ChallengeStatus.NARROWING;
        }

        _touchSession(session);
        emit ChallengeStepped(txId, dispute.round, dispute.left, dispute.right, dispute.narrowingComplete);
    }

    function recoverChallenge(bytes32 txId) external {
        ChallengeSession storage session = sessions[txId];
        require(session.exists && session.status != ChallengeStatus.RESOLVED, "no recoverable challenge");
        require(_isTimedOut(session), "challenge still active");

        session.recovery.count += 1;
        session.recovery.lastRecoveredAt = block.timestamp;
        session.recovery.lastPriorRound = session.dispute.round;
        session.recovery.lastPriorStatus = session.status;
        session.operator = msg.sender;

        if (session.dispute.narrowingComplete) {
            session.status = ChallengeStatus.READY_FOR_REPLAY;
        } else if (session.dispute.round > 0) {
            session.status = ChallengeStatus.RECOVERED;
        } else if (session.responder != address(0)) {
            session.status = ChallengeStatus.RESPONDED;
        } else {
            session.status = ChallengeStatus.OPEN;
        }

        _touchSession(session);
        emit ChallengeRecovered(txId, msg.sender, session.status);
    }

    function replayChallenge(
        bytes32 txId,
        uint256 targetStep,
        bytes32 expectedHash,
        bytes32 claimedHash,
        bool lengthMismatch
    ) external {
        ChallengeSession storage session = sessions[txId];
        require(session.exists && _isActiveStatus(session.status), "no active challenge");
        require(!_isTimedOut(session), "challenge timed out");
        require(session.dispute.narrowingComplete, "dispute not narrowed");
        require(targetStep == session.dispute.targetStep, "target step mismatch");

        bool passed = !lengthMismatch && expectedHash == claimedHash;
        session.dispute.replayExecuted = true;
        session.dispute.replayPassed = passed;
        session.evidence.targetStep = targetStep;
        session.evidence.expectedHash = expectedHash;
        session.evidence.claimedHash = claimedHash;
        session.status = ChallengeStatus.REPLAYED;
        _touchSession(session);

        emit ChallengeReplayed(txId, targetStep, passed);
    }

    function resolveChallenge(bytes32 txId, uint256 resolutionBits) external {
        RollupTransaction storage transaction = transactions[txId];
        ChallengeSession storage session = sessions[txId];
        require(transaction.exists, "tx missing");
        require(session.exists && _isActiveStatus(session.status), "no resolvable challenge");

        bool challengeSuccess = resolutionBits != 0 || (session.dispute.replayExecuted && !session.dispute.replayPassed);
        session.arbitrator = msg.sender;
        session.status = ChallengeStatus.RESOLVED;
        session.resolvedAt = block.timestamp;
        session.lastUpdatedAt = block.timestamp;
        session.challengeSuccess = challengeSuccess;
        session.resolutionBits = resolutionBits;
        session.evidence.mismatchBits |= resolutionBits;

        if (challengeSuccess) {
            transaction.status = TxStatus.SLASHED;
        }

        emit ChallengeResolved(txId, challengeSuccess, transaction.status);
    }

    function finalizeExpired(bytes32[] calldata txIds) external {
        for (uint256 index = 0; index < txIds.length; index++) {
            bytes32 txId = txIds[index];
            RollupTransaction storage transaction = transactions[txId];
            if (
                transaction.exists &&
                transaction.status == TxStatus.PENDING &&
                block.timestamp >= transaction.challengeDeadline &&
                !_isActiveSession(txId)
            ) {
                transaction.status = TxStatus.FINALIZED;
                emit TransactionFinalized(txId);
            }
        }
    }

    function verifyDAField(
        bytes32 txId,
        bytes32 fieldKeyHash,
        bytes32 valueHash,
        bytes32[] calldata siblingHashes,
        bool[] calldata siblingOnLeft
    ) external view returns (bool available, bool valid) {
        RollupTransaction storage transaction = transactions[txId];
        require(transaction.exists, "tx missing");
        available = daRegistry.isAvailable(transaction.commit.daPointer);
        valid = available
            && MerkleVerifier.verify(
                transaction.commit.daMerkleRoot,
                fieldKeyHash,
                valueHash,
                siblingHashes,
                siblingOnLeft
            );
    }

    function getTransaction(bytes32 txId) external view returns (RollupTransaction memory) {
        require(transactions[txId].exists, "tx missing");
        return transactions[txId];
    }

    function getChallengeSession(bytes32 txId) external view returns (ChallengeSession memory) {
        require(sessions[txId].exists, "session missing");
        return sessions[txId];
    }

    function isChallengeTimedOut(bytes32 txId) external view returns (bool) {
        require(sessions[txId].exists, "session missing");
        return _isTimedOut(sessions[txId]);
    }

    function _touchSession(ChallengeSession storage session) internal {
        session.lastUpdatedAt = block.timestamp;
        session.timeoutAt = block.timestamp + defaultChallengeTimeoutSeconds;
    }

    function _isTimedOut(ChallengeSession storage session) internal view returns (bool) {
        return block.timestamp > session.timeoutAt;
    }

    function _isActiveSession(bytes32 txId) internal view returns (bool) {
        ChallengeSession storage session = sessions[txId];
        return session.exists && session.status != ChallengeStatus.RESOLVED;
    }

    function _isActiveStatus(ChallengeStatus status) internal pure returns (bool) {
        return
            status == ChallengeStatus.OPEN ||
            status == ChallengeStatus.RESPONDED ||
            status == ChallengeStatus.NARROWING ||
            status == ChallengeStatus.READY_FOR_REPLAY ||
            status == ChallengeStatus.REPLAYED ||
            status == ChallengeStatus.RECOVERED;
    }
}

